// Writes host redirect files from src/data/redirects.json so there is one source of truth.
//   public/_redirects  Netlify and Cloudflare Pages
//   public/_headers    noindex header for retired paths
//   vercel.json        Vercel
import { readFile, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const data = JSON.parse(await readFile(path.join(root, 'src/data/redirects.json'), 'utf8'));

const lines = [
  '# Generated by scripts/gen-redirects.mjs from src/data/redirects.json. Do not edit by hand.',
  '# Every rule is a single hop to a page that returns 200.',
  '',
];
for (const r of data.redirects) lines.push(`${r.from}  ${r.to}  ${r.status ?? 301}`);
lines.push('');
lines.push('# Retired paths need no rule: they fall through to the 404 page, which is noindex,');
lines.push('# and public/_headers adds an X-Robots-Tag so they drop out of the index.');
for (const g of data.gone) lines.push(`# retired: ${g.from}`);
await writeFile(path.join(root, 'public/_redirects'), lines.join('\n') + '\n');

const headers = ['# Generated by scripts/gen-redirects.mjs. Do not edit by hand.', ''];
for (const g of data.gone) headers.push(g.from, '  X-Robots-Tag: noindex', '');
await writeFile(path.join(root, 'public/_headers'), headers.join('\n'));

const vercel = {
  cleanUrls: true,
  trailingSlash: false,
  redirects: [
    ...data.redirects.map((r) => ({
      source: r.from,
      destination: r.to,
      statusCode: r.status ?? 301,
    })),
  ],
  headers: data.gone.map((g) => ({
    source: g.from.replace('/*', '/(.*)'),
    headers: [{ key: 'X-Robots-Tag', value: 'noindex' }],
  })),
};
await writeFile(path.join(root, 'vercel.json'), JSON.stringify(vercel, null, 2) + '\n');
console.log(`redirects: ${data.redirects.length} rules, ${data.gone.length} retired patterns`);
